using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalSentenceCount { get; set; }
    public int SummarySentenceCount { get; set; }
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

public partial class DocumentSummarizationService
{
    private static readonly HashSet<string> StopWords =
    [
        "a", "an", "the", "and", "or", "but", "is", "are", "was", "were",
        "in", "on", "at", "to", "for", "of", "with", "by", "from", "it",
        "this", "that", "as", "be", "has", "have", "had", "not", "no",
        "do", "does", "did", "will", "would", "could", "should", "may",
        "can", "if", "then", "so", "its", "his", "her", "their", "our",
        "my", "your", "he", "she", "they", "we", "you", "i", "me", "us",
        "him", "them", "been", "being", "which", "who", "whom", "what",
        "where", "when", "how", "all", "each", "every", "both", "few",
        "more", "most", "other", "some", "such", "than", "too", "very",
        "just", "about", "above", "after", "again", "also", "am", "any",
        "because", "before", "between", "during", "into", "through", "up",
        "out", "over", "own", "same", "here", "there", "while"
    ];

    [GeneratedRegex(@"(?<=[.!?])\s+")]
    private static partial Regex SentenceSplitter();

    [GeneratedRegex(@"[^\w\s]")]
    private static partial Regex PunctuationRemover();

    /// <summary>
    /// Produces an extractive summary by scoring sentences based on word frequency.
    /// </summary>
    public (string Summary, int OriginalCount, int SummaryCount) Summarize(
        string documentText, int maxSentences)
    {
        var sentences = SentenceSplitter()
            .Split(documentText.Trim())
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .ToList();

        if (sentences.Count <= maxSentences)
        {
            return (string.Join(" ", sentences), sentences.Count, sentences.Count);
        }

        var wordFrequencies = ComputeWordFrequencies(sentences);

        var scoredSentences = sentences
            .Select((sentence, index) => (Index: index, Score: ScoreSentence(sentence, wordFrequencies)))
            .OrderByDescending(s => s.Score)
            .Take(maxSentences)
            .OrderBy(s => s.Index) // preserve original order
            .Select(s => sentences[s.Index]);

        var summary = string.Join(" ", scoredSentences);
        return (summary, sentences.Count, maxSentences);
    }

    private static Dictionary<string, double> ComputeWordFrequencies(List<string> sentences)
    {
        var freq = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);

        foreach (var sentence in sentences)
        {
            foreach (var word in GetWords(sentence))
            {
                if (!StopWords.Contains(word))
                {
                    freq[word] = freq.GetValueOrDefault(word) + 1;
                }
            }
        }

        // Normalize by max frequency
        if (freq.Count > 0)
        {
            var maxFreq = freq.Values.Max();
            foreach (var key in freq.Keys)
            {
                freq[key] /= maxFreq;
            }
        }

        return freq;
    }

    private static double ScoreSentence(string sentence, Dictionary<string, double> wordFrequencies)
    {
        var words = GetWords(sentence);
        if (words.Length == 0) return 0;

        return words.Sum(w => wordFrequencies.GetValueOrDefault(w)) / words.Length;
    }

    private static string[] GetWords(string text)
    {
        var cleaned = PunctuationRemover().Replace(text.ToLowerInvariant(), "");
        return cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries);
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly DocumentSummarizationService _summarizer;

    public SummarizeController(DocumentSummarizationService summarizer)
    {
        _summarizer = summarizer;
    }

    /// <summary>
    /// Accepts document text and returns a concise extractive summary.
    /// </summary>
    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var (summary, originalCount, summaryCount) =
            _summarizer.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalSentenceCount = originalCount,
            SummarySentenceCount = summaryCount
        });
    }
}

